const update = $input.first().json;
const message = update.message || update.edited_message || {};
const callback = update.callback_query || {};
const chatId = message.chat?.id ?? callback.message?.chat?.id;
if (chatId === undefined || chatId === null) {
  throw new Error('Telegram update did not contain a chat ID.');
}
return [{ json: {
  chat_id: chatId,
  user_text: message.text || message.caption || '',
  callback_data: callback.data || null,
  callback_query_id: callback.id || null,
  message_id: message.message_id ?? callback.message?.message_id ?? null,
  action: callback.data || 'search',
  received_at: new Date().toISOString()
} }];

const input = $input.first().json;
const callback = input.callback_data;
return [{ json: {
  chat_id: input.chat_id,
  user_text: input.user_text || callback || '',
  action: callback || 'search',
  callback_data: callback,
  message_id: input.message_id,
  state_key: String(input.chat_id)
} }];

const input = $input.first().json;
const store = $getWorkflowStaticData('global');
store.chats = store.chats || {};
const previous = store.chats[String(input.chat_id)] || {};
return [{ json: { ...input, previous_context: previous } }];

const response = $input.first().json || {};
const base = $node['Load Conversation Memory'].json || {};
const action = base.action || 'search';
const previous = base.previous_context || {};
let parsed = {};
let parse_error = false;
const content = response.choices?.[0]?.message?.content;
if (action === 'direct') parsed = { ...previous, direct_only: true };
else if (action === 'cheapest') parsed = { ...previous, sort: 'price' };
else if (action === 'change_date') parsed = { ...previous, departure_date: null, return_date: null, needs_date: true };
else if (action === 'new_search') parsed = {};
else if (content) { try { parsed = { ...previous, ...JSON.parse(content) }; } catch (error) { parse_error = true; parsed = { ...previous }; } }
else { parse_error = true; parsed = { ...previous }; }
const userText = String(base.user_text || '');
const normalize = value => String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f\u064b-\u065f\u0670\u0640]/g, '').replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/[٠-٩]/g, digit => String('٠١٢٣٤٥٦٧٨٩'.indexOf(digit)));
const cities = [
  { iata:'IST', city:'Istanbul', aliases:['اسطنبول','إسطنبول','استانبول','istanbul'] },
  { iata:'DOH', city:'Doha', aliases:['الدوحه','الدوحة','دوحه','دوحة','doha'] },
  { iata:'LON', city:'London', aliases:['لندن','london'] },
  { iata:'PAR', city:'Paris', aliases:['باريس','paris'] },
  { iata:'RUH', city:'Riyadh', aliases:['الرياض','رياض','riyadh'] },
  { iata:'CAI', city:'Cairo', aliases:['القاهره','القاهرة','قاهره','قاهرة','cairo'] },
  { iata:'DXB', city:'Dubai', aliases:['دبي','dubai'] },
  { iata:'AUH', city:'Abu Dhabi', aliases:['ابوظبي','أبوظبي','ابو ظبي','abu dhabi'] },
  { iata:'JED', city:'Jeddah', aliases:['جده','جدة','jeddah'] },
  { iata:'MED', city:'Medina', aliases:['المدينه','المدينة','المدينه المنوره','المدينة المنورة','medina'] },
  { iata:'AMM', city:'Amman', aliases:['عمان','عمّان','amman'] },
  { iata:'BEY', city:'Beirut', aliases:['بيروت','beirut'] },
  { iata:'KWI', city:'Kuwait City', aliases:['الكويت','مدينة الكويت','kuwait'] },
  { iata:'MCT', city:'Muscat', aliases:['مسقط','muscat'] },
  { iata:'IST', city:'Istanbul', aliases:['مطار اسطنبول','مطار إسطنبول'] },
  { iata:'LHR', city:'London Heathrow', aliases:['هيثرو','heathrow'] },
  { iata:'CDG', city:'Paris Charles de Gaulle', aliases:['شارل ديغول','شارل ديجول','charles de gaulle'] }
];
const normalizedText = normalize(userText);
const findCity = text => { const value = normalize(text); const found = cities.flatMap(city => city.aliases.map(alias => ({ city, alias:normalize(alias) }))).sort((a,b) => b.alias.length-a.alias.length).find(entry => value.includes(entry.alias)); return found ? found.city : null; };
const routeMatch = normalizedText.match(/(?:^|\s)(?:من|from)\s*(.+?)\s*(?:الى|الي|to)\s*(.+?)(?=\s+(?:بتاريخ|في|يوم|on|date)\b|[,،\n]|$)/u);
if (action === 'search' || action === 'new_search') {
  if (routeMatch) {
    const originCity = findCity(routeMatch[1]);
    const destinationCity = findCity(routeMatch[2]);
    if (originCity) { parsed.origin_city = originCity.city; parsed.origin_iata = originCity.iata; }
    if (destinationCity) { parsed.destination_city = destinationCity.city; parsed.destination_iata = destinationCity.iata; }
  }
  const digitText = userText.replace(/[٠-٩]/g, digit => String('٠١٢٣٤٥٦٧٨٩'.indexOf(digit)));
  const dateMatch = digitText.match(/(?:^|\D)(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})(?!\d)|(?:^|\D)(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})(?!\d)/);
  if (dateMatch) {
    const year = Number(dateMatch[1] || dateMatch[6]);
    const month = Number(dateMatch[2] || dateMatch[5]);
    const day = Number(dateMatch[3] || dateMatch[4]);
    const date = new Date(Date.UTC(year, month - 1, day));
    if (date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day) parsed.departure_date = date.toISOString().slice(0,10);
  }
}
if (parsed.origin_iata && !parsed.origin) parsed.origin = parsed.origin_iata;
if (parsed.destination_iata && !parsed.destination) parsed.destination = parsed.destination_iata;
if (parsed.origin_iata && parsed.destination_iata && parsed.departure_date) parse_error = false;
parsed.chat_id = base.chat_id;
parsed.action = action;
parsed.state_key = base.state_key;
parsed.parse_error = parse_error;
parsed.user_language = parsed.user_language || (/[^\x00-\x7F]/.test(userText) ? 'ar' : 'en');
parsed.trip_type = parsed.trip_type === 'round_trip' ? 'round_trip' : 'one_way';
parsed.passengers = Math.min(9, Math.max(1, Number(parsed.passengers) || 1));
parsed.currency = /^[A-Za-z]{3}$/.test(String(parsed.currency || '')) ? String(parsed.currency).toUpperCase() : 'USD';
parsed.cabin_class = ['economy','premium_economy','business','first'].includes(parsed.cabin_class) ? parsed.cabin_class : 'economy';
parsed.direct_only = Boolean(parsed.direct_only);
parsed.sort = parsed.sort === 'recommended' ? 'recommended' : 'price';
return [{ json: parsed }];

const x = $input.first().json;
const store = $getWorkflowStaticData('global');
store.chats = store.chats || {};
const fields = ['origin_city','origin_iata','destination_city','destination_iata','departure_date','return_date','trip_type','passengers','cabin_class','currency','direct_only','sort','user_language','max_price'];
const context = {};
for (const field of fields) { if (x[field] !== undefined) context[field] = x[field]; }
context.updated_at = new Date().toISOString();
store.chats[String(x.chat_id)] = context;
const missing = [];
if (!/^[A-Z]{3}$/.test(String(x.origin_iata || '').toUpperCase())) missing.push('origin_iata');
if (!/^[A-Z]{3}$/.test(String(x.destination_iata || '').toUpperCase())) missing.push('destination_iata');
if (!/^\d{4}-\d{2}-\d{2}$/.test(String(x.departure_date || ''))) missing.push('departure_date');
if (x.trip_type === 'round_trip' && !/^\d{4}-\d{2}-\d{2}$/.test(String(x.return_date || ''))) missing.push('return_date');
const ready = missing.length === 0 && !x.needs_date;
return [{ json: { ...x, origin_iata: String(x.origin_iata || '').toUpperCase(), destination_iata: String(x.destination_iata || '').toUpperCase(), missing_fields: missing, ready } }];

const request = $('Save and Validate Flight Request').first().json;
const google = $('Search Google Flights (SerpApi)').first().json || {};
const duffel = $('Search Duffel Offers').first().json || {};
const googleGroups = [...(Array.isArray(google.best_flights) ? google.best_flights : []), ...(Array.isArray(google.other_flights) ? google.other_flights : [])];
let flights = googleGroups.map(group => {
  const segments = (Array.isArray(group.flights) ? group.flights : []).map(segment => ({ airline: segment.airline || 'Unknown', flight_number: segment.flight_number || '', departure: segment.departure_airport?.time || null, arrival: segment.arrival_airport?.time || null, from: segment.departure_airport?.id || '', to: segment.arrival_airport?.id || '', duration: segment.duration ?? null }));
  return { source: 'Google Flights', price: Number(group.price), currency: google.currency || request.currency || 'USD', total_duration: group.total_duration ?? null, stops: Math.max(0, segments.length - 1), segments };
}).filter(flight => Number.isFinite(flight.price));
const offers = Array.isArray(duffel.data?.offers) ? duffel.data.offers : [];
flights.push(...offers.map(offer => {
  const slices = Array.isArray(offer.slices) ? offer.slices : [];
  const segments = slices.flatMap(slice => (Array.isArray(slice.segments) ? slice.segments : []).map(segment => ({ airline: segment.marketing_carrier?.name || segment.operating_carrier?.name || 'Unknown', flight_number: segment.marketing_carrier_flight_number || '', departure: segment.departing_at || null, arrival: segment.arriving_at || null, from: segment.origin?.iata_code || '', to: segment.destination?.iata_code || '', duration: slice.duration || null })));
  return { source: 'Duffel', offer_id: offer.id || null, price: Number(offer.total_amount), currency: offer.total_currency || request.currency || 'USD', total_duration: slices.map(slice => slice.duration).filter(Boolean).join(' + ') || null, stops: Math.max(0, segments.length - slices.length), segments };
}).filter(flight => Number.isFinite(flight.price)));
const errorText = value => typeof value === 'string' ? value : value?.message || value?.description || null;
const providerErrors = [errorText(google.error) || errorText(google.message), errorText(duffel.error) || errorText(duffel.message) || (Array.isArray(duffel.errors) ? duffel.errors.map(errorText).filter(Boolean).join('; ') : null)].filter(Boolean);
if (request.direct_only) flights = flights.filter(flight => flight.stops === 0);
const maxPrice = request.max_price === null || request.max_price === undefined || request.max_price === '' ? NaN : Number(request.max_price);
if (Number.isFinite(maxPrice)) flights = flights.filter(flight => flight.price <= maxPrice);
flights.sort((a, b) => request.sort === 'recommended' ? (a.stops - b.stops || a.price - b.price) : a.price - b.price);
flights = flights.slice(0, 5);
return [{ json: { chat_id: request.chat_id, user_language: request.user_language || 'ar', flights, provider_errors: providerErrors, searched_at: new Date().toISOString() } }];

const result = $input.first()?.json || {};
const flights = Array.isArray(result.flights) ? result.flights : [];
const safeFlights = flights.filter(flight => flight && Number.isFinite(Number(flight.price)) && Array.isArray(flight.segments));
safeFlights.sort((left, right) => Number(left.price) - Number(right.price));
return [{ json: { ...result, flights: safeFlights.slice(0, 5), provider_errors: Array.isArray(result.provider_errors) ? result.provider_errors : [] } }];

const x = $input.first().json || {};
const flights = Array.isArray(x.flights) ? x.flights : [];
const language = x.user_language || 'ar';
const line = '-------------------';
let text;
if (!flights.length && Array.isArray(x.provider_errors) && x.provider_errors.length >= 2) {
  text = language === 'en' ? 'Flight search is temporarily unavailable. Please try again shortly.' : 'البحث عن الرحلات غير متاح مؤقتاً. يرجى المحاولة بعد قليل.';
} else if (!flights.length) {
  text = language === 'en' ? 'No matching flights were found. Try another date, route, or filter.' : 'لم يتم العثور على رحلات مطابقة. جرّب تاريخاً أو مساراً أو تصفية أخرى.';
} else {
  const heading = language === 'en' ? '✈️ Flight results' : '✈️ نتائج الرحلات';
  const blocks = flights.map((flight, index) => {
    const segments = Array.isArray(flight.segments) ? flight.segments : [];
    const first = segments[0] || {};
    const last = segments[segments.length - 1] || first;
    const airline = first.airline || flight.source || (language === 'en' ? 'Unknown airline' : 'شركة طيران غير معروفة');
    const origin = first.from || x.origin_iata || '?';
    const destination = last.to || x.destination_iata || '?';
    const stops = flight.stops === 0 ? (language === 'en' ? 'Direct' : 'مباشرة') : `${Number(flight.stops) || 0} ${language === 'en' ? 'stop(s)' : 'توقف'}`;
    const departure = first.departure || '?';
    const arrival = last.arrival || '?';
    const source = flight.source || (language === 'en' ? 'Flight provider' : 'مزود الرحلات');
    if (language === 'en') return `${index + 1}. ✈️ ${airline} — 💰 ${flight.price ?? '?'} ${flight.currency || ''}\n🛫 Route: ${origin} ➡️ ${destination} (${stops})\n🕒 Departure: ${departure} | Arrival: ${arrival}\n🔍 Source: ${source}`;
    return `${index + 1}. ✈️ ${airline} — 💰 ${flight.price ?? '?'} ${flight.currency || ''}\n🛫 المسار: ${origin} ⬅️ ${destination} (${stops})\n🕒 الإقلاع: ${departure} | الوصول: ${arrival}\n🔍 المصدر: ${source}`;
  });
  text = `${heading}\n\n${blocks.join(`\n${line}\n`)}\n\n${language === 'en' ? 'Prices and availability can change.' : 'قد تتغير الأسعار والتوافر.'}`;
}
return [{ json: { chat_id: x.chat_id, telegram_text: text } }];

const x = $input.first().json;
const language = x.user_language || 'ar';
const text = x.parse_error ? (language === 'en' ? 'I could not understand that request. Send a route and travel date, for example: London to Paris on 2026-10-15.' : 'لم أتمكن من فهم الطلب. أرسل المسار وتاريخ السفر، مثال: من لندن إلى باريس بتاريخ 2026-10-15.') : (language === 'en' ? 'Please provide the missing details: ' : 'أرسل التفاصيل الناقصة: ') + x.missing_fields.map(field => ({origin_iata:language === 'en' ? 'origin airport/city' : 'مدينة أو رمز مطار المغادرة',destination_iata:language === 'en' ? 'destination airport/city' : 'مدينة أو رمز مطار الوصول',departure_date:language === 'en' ? 'departure date (YYYY-MM-DD)' : 'تاريخ المغادرة (YYYY-MM-DD)',return_date:language === 'en' ? 'return date (YYYY-MM-DD)' : 'تاريخ العودة (YYYY-MM-DD)'}[field] || field)).join(', ');
return [{ json: { chat_id: x.chat_id, telegram_text: text } }];
